  "ListMenuPrintEntries": {
    returnType: "static void",
    params: "struct ListMenu *list, u16 startIndex, u16 yOffset, u16 count",
    callsTo: ["GetFontAttribute","ListMenuPrint","itemPrintFunc"],
    lineCount: 15,
    bodyC: "s32 i;\n    u8 x, y;\n    u8 yMultiplier = GetFontAttribute(list->template.fontId, FONTATTR_MAX_LETTER_HEIGHT) + list->template.itemVerticalPadding;\n\n    for (i = 0; i < count; i++)\n    {\n        if (list->template.items[startIndex].id != LIST_HEADER)\n            x = list->template.item_X;\n        else\n            x = list->template.header_X;\n\n        y = (yOffset + i) * yMultiplier + list->template.upText_Y;\n        if (list->template.itemPrintFunc != NULL)\n            list->template.itemPrintFunc(list->template.windowId, list->template.items[startIndex].id, y);\n\n        ListMenuPrint(list, list->template.items[startIndex].name, x, y);\n        startIndex++;\n    }",
  },
