  "ListMenuUpdateSelectedRowIndexAndScrollOffset": {
    returnType: "static u8",
    params: "struct ListMenu *list, bool8 movingDown",
    lineCount: 73,
    bodyC: "u16 selectedRow = list->selectedRow;\n    u16 scrollOffset = list->scrollOffset;\n    u16 newRow;\n    u32 newScroll;\n\n    if (!movingDown)\n    {\n        if (list->template.maxShowed == 1)\n            newRow = 0;\n        else\n            newRow = list->template.maxShowed - ((list->template.maxShowed / 2) + (list->template.maxShowed % 2)) - 1;\n\n        if (scrollOffset == 0)\n        {\n            while (selectedRow != 0)\n            {\n                selectedRow--;\n                if (list->template.items[scrollOffset + selectedRow].id != LIST_HEADER)\n                {\n                    list->selectedRow = selectedRow;\n                    return 1;\n                }\n            }\n\n            return 0;\n        }\n        else\n        {\n            while (selectedRow > newRow)\n            {\n                selectedRow--;\n                if (list->template.items[scrollOffset + selectedRow].id != LIST_HEADER)\n                {\n                    list->selectedRow = selectedRow;\n                    return 1;\n                }\n            }\n\n            newScroll = scrollOffset - 1;\n        }\n    }\n    else\n    {\n        if (list->template.maxShowed == 1)\n            newRow = 0;\n        else\n            newRow = ((list->template.maxShowed / 2) + (list->template.maxShowed % 2));\n\n        if (scrollOffset == list->template.totalItems - list->template.maxShowed)\n        {\n            while (selectedRow < list->template.maxShowed - 1)\n            {\n                selectedRow++;\n                if (list->template.items[scrollOffset + selectedRow].id != LIST_HEADER)\n                {\n                    list->selectedRow = selectedRow;\n                    return 1;\n                }\n            }\n\n            return 0;\n        }\n        else\n        {\n            while (selectedRow < newRow)\n            {\n                selectedRow++;\n                if (list->template.items[scrollOffset + selectedRow].id != LIST_HEADER)\n                {\n                    list->selectedRow = selectedRow;\n                    return 1;\n                }\n            }\n\n            newScroll = scrollOffset + 1;\n        }\n    }\n\n    list->selectedRow = newRow;\n    list->scrollOffset = newScroll;\n    return 2;",
  },
  "ListMenu_ProcessInput": {
    returnType: "s32",
    params: "u8 listTaskId",
    callsTo: ["JOY_NEW","JOY_REPEAT","ListMenuChangeSelection"],
    lineCount: 53,
    bodyC: "struct ListMenu *list = (void *) gTasks[listTaskId].data;\n\n    if (JOY_NEW(A_BUTTON))\n    {\n        return list->template.items[list->scrollOffset + list->selectedRow].id;\n    }\n    else if (JOY_NEW(B_BUTTON))\n    {\n        return LIST_CANCEL;\n    }\n    else if (JOY_REPEAT(DPAD_UP))\n    {\n        ListMenuChangeSelection(list, TRUE, 1, FALSE);\n        return LIST_NOTHING_CHOSEN;\n    }\n    else if (JOY_REPEAT(DPAD_DOWN))\n    {\n        ListMenuChangeSelection(list, TRUE, 1, TRUE);\n        return LIST_NOTHING_CHOSEN;\n    }\n    else  \n    {\n        bool16 rightButton, leftButton;\n        switch (list->template.scrollMultiple)\n        {\n        case LIST_NO_MULTIPLE_SCROLL:\n        default:\n            leftButton = FALSE;\n            rightButton = FALSE;\n            break;\n        case LIST_MULTIPLE_SCROLL_DPAD:\n             \n            leftButton = JOY_REPEAT(DPAD_LEFT);\n            rightButton = JOY_REPEAT(DPAD_RIGHT);\n            break;\n        case LIST_MULTIPLE_SCROLL_L_R:\n             \n            leftButton = JOY_REPEAT(L_BUTTON);\n            rightButton = JOY_REPEAT(R_BUTTON);\n            break;\n        }\n\n        if (leftButton)\n        {\n            ListMenuChangeSelection(list, TRUE, list->template.maxShowed, FALSE);\n            return LIST_NOTHING_CHOSEN;\n        }\n        else if (rightButton)\n        {\n            ListMenuChangeSelection(list, TRUE, list->template.maxShowed, TRUE);\n            return LIST_NOTHING_CHOSEN;\n        }\n        else\n        {\n            return LIST_NOTHING_CHOSEN;\n        }\n    }",
  },
